// CTMIDIImportTests.swift — MIDI files to ct-song/1 (docs/music_tracker.md,
// "MIDI import"). Every MIDI file here is generated by the test; the driver
// test reads the local clean ROM.
import XCTest
@testable import ChronoForgeCore

final class CTMIDIImportTests: XCTestCase {
    typealias E = CTMIDIFile.Event

    /// 480 ticks a quarter. Channel 1 (program 5): a melody with a chord, an
    /// off-grid note and a long tied note; channel 2 (program 33): bass in two
    /// octaves; channel 10: two drum keys. 120 BPM, then 90 from bar 3.
    static func fixture(extraChannels: Int = 0) -> [UInt8] {
        let q = 480
        var tempo: [E] = [.init(tick: 0, kind: .tempo(500_000)), .init(tick: 8 * q, kind: .tempo(666_667))]
        tempo.sort { $0.tick < $1.tick }
        func note(_ c: Int, _ key: Int, _ start: Int, _ length: Int) -> [E] {
            [.init(tick: start, kind: .noteOn(channel: c, key: key, velocity: 100)), .init(tick: start + length, kind: .noteOff(channel: c, key: key))]
        }
        var melody: [E] = [.init(tick: 0, kind: .program(channel: 0, program: 5))]
        melody += note(0, 60, 0, q)                      // C4, a quarter
        melody += note(0, 64, q, q / 2)                  // E4, an eighth
        melody += note(0, 67, q + q / 2 + 7, q / 2 - 7)  // G4, 7 ticks late (0.35 steps)
        melody += note(0, 72, 2 * q, q)                  // a chord: C5 is kept,
        melody += note(0, 55, 2 * q, q)                  // G3 is dropped
        melody += note(0, 62, 4 * q, 7 * q)              // D4 for 7 quarters (168 steps: tied, across the tempo change)
        var bass: [E] = [.init(tick: 0, kind: .program(channel: 1, program: 33))]
        bass += note(1, 36, 0, 2 * q)                    // C2
        bass += note(1, 43, 2 * q, 2 * q)                // G2
        bass += note(1, 48, 4 * q, 4 * q)                // C3
        var drums: [E] = []
        for b in 0..<8 { drums += note(9, b % 2 == 0 ? 36 : 38, b * q, q / 4) }
        var tracks = [tempo, melody, bass, drums]
        for k in 0..<extraChannels { tracks.append(note(2 + k, 60, 0, q)) }
        return CTMIDIFile.write(division: q, tracks: tracks)
    }

    static func options() -> CTMIDIImport.Options {
        var o = CTMIDIImport.Options()
        o.programs = [5: 1, 33: 2]
        o.drums = [.init(key: 36, sample: 3, note: 60, pan: 0x40), .init(key: 38, sample: 4, note: 62)]
        return o
    }

    func testParseWhatTheWriterWrites() throws {
        let file = try CTMIDIFile(bytes: Self.fixture())
        XCTAssertEqual(file.format, 1)
        XCTAssertEqual(file.division, 480)
        let ons = file.events.filter { if case .noteOn = $0.kind { return true } else { return false } }
        XCTAssertEqual(ons.count, 6 + 3 + 8)
        XCTAssertEqual(file.events.first?.kind, .tempo(500_000))
        // Running status, velocity-0 offs and a sysex: one track written by hand.
        let body: [UInt8] = [0, 0xF0, 2, 0x7E, 0xF7,          // sysex, skipped
                             0, 0x90, 60, 90, 120, 60, 0,       // on, then "on" velocity 0 (running status)
                             0, 0xFF, 0x2F, 0]
        let raw = Array("MThd".utf8) + [0, 0, 0, 6, 0, 0, 0, 1, 0, 120] + Array("MTrk".utf8) + [0, 0, 0, UInt8(body.count)] + body
        let parsed = try CTMIDIFile(bytes: raw)
        XCTAssertEqual(parsed.events, [.init(tick: 0, kind: .noteOn(channel: 0, key: 60, velocity: 90)),
                                       .init(tick: 120, kind: .noteOff(channel: 0, key: 60))])
        XCTAssertThrowsError(try CTMIDIFile(bytes: Array("RIFF".utf8) + [UInt8](repeating: 0, count: 20)))
        var smpte = raw
        smpte[12] = 0xE7
        XCTAssertThrowsError(try CTMIDIFile(bytes: smpte)) { XCTAssertTrue("\($0)".contains("SMPTE"), "\($0)") }
    }

    func testTempoIsTheDriversFormula() {
        // 120 BPM is 48 steps a second: 48 x 256 x 0.00525 = 64.5 a pass; t = $3D gives 61 + 61 x 20 / 256 = 65.
        let t = CTMIDIImport.tempoByte(bpm: 120)
        XCTAssertEqual(t.byte, 0x3D)
        XCTAssertEqual(t.tempo, 65)
        XCTAssertEqual(t.bpm, 65.0 / 256 / 0.00525 * 60 / 24, accuracy: 1e-9)
        // One driver tempo unit is 60 / (256 x 0.00525 x 24) = 1.86 BPM, and t + t x 20 / 256
        // skips a value now and then, so the played tempo is within one unit.
        let unit = 60 / (256 * CTSongTempoMap.secondsPerPass * 24)
        for bpm in stride(from: 40.0, through: 470, by: 3) {
            XCTAssertLessThanOrEqual(abs(CTMIDIImport.tempoByte(bpm: bpm).bpm - bpm), unit, "\(bpm)")
        }
    }

    func testConvertMapsVoicesNotesProgramsAndDrums() throws {
        let (text, report) = try CTMIDIImport.convert(try CTMIDIFile(bytes: Self.fixture()), options: Self.options())
        let (data, tables) = try CTSongListing.assembleSong(text)
        XCTAssertEqual(report.sequenceBytes, data.count)
        XCTAssertEqual(tables.samples, [1, 2, 3, 4])
        XCTAssertEqual(report.samples, [1, 2, 3, 4])
        let kit = try CTDrumKit(bytes: try XCTUnwrap(tables.drums))
        XCTAssertEqual(kit.pads[0], .init(sample: 0x22, note: 60, pan: 0x40))
        XCTAssertEqual(kit.pads[1], .init(sample: 0x23, note: 62, pan: 0x80))
        XCTAssertTrue(kit.pads[2].isEmpty)
        let voices: [Int] = report.voices.map { $0.channel }
        XCTAssertEqual(voices, [1, 2, 10])
        XCTAssertEqual(report.voices[0].droppedFromChords, 1)
        XCTAssertEqual(report.voices[2].drums, true)
        XCTAssertEqual(report.programs.map(\.program), [5, 33])
        XCTAssertEqual(report.programs.map(\.slot), [0, 1])
        // Quantization: the late G4 is 0.35 steps off; nothing else is.
        XCTAssertEqual(report.maxErrorSteps, 0.35, accuracy: 1e-9)
        XCTAssertEqual(report.steps, 288)
        XCTAssertEqual(report.tempo.map(\.step), [0, 192])
        XCTAssertEqual(report.tempo.map(\.byte), [0x3D, CTMIDIImport.tempoByte(bpm: 90).byte])

        let doc = CTSongDocument(listing: text)
        let timeline = try CTSongTimeline(doc, tables: tables)
        let melody = timeline.tracks[0].notes
        XCTAssertEqual(melody.map(\.start), [0, 24, 36, 48, 96])
        XCTAssertEqual(melody.map(\.number), [60, 64, 67, 72, 62])
        XCTAssertEqual(melody.map(\.length), [24, 12, 12, 24, 168])
        XCTAssertEqual(melody.last?.ties.isEmpty, false)
        XCTAssertTrue(melody.allSatisfy { $0.sample == 0x20 })
        let bass = timeline.tracks[1].notes
        XCTAssertEqual(bass.map(\.number), [36, 43, 48])
        XCTAssertTrue(bass.allSatisfy { $0.sample == 0x21 })
        let drums = timeline.tracks[2].notes
        XCTAssertEqual(drums.count, 8)
        XCTAssertTrue(drums.allSatisfy(\.drum))
        XCTAssertEqual(drums.map(\.sample), [0x22, 0x23, 0x22, 0x23, 0x22, 0x23, 0x22, 0x23])
        XCTAssertEqual(drums.map(\.number), [60, 62, 60, 62, 60, 62, 60, 62])
        // Every track loops after 288 steps; the tempo change sits in track 0's tied D4.
        XCTAssertTrue(timeline.tracks.prefix(3).allSatisfy { $0.loopEnd == 288 })
        XCTAssertEqual(timeline.tempo.map(\.step), [0, 192])
    }

    func testRefusals() throws {
        let file = try CTMIDIFile(bytes: Self.fixture())
        func refused(_ f: CTMIDIFile, _ o: CTMIDIImport.Options, _ text: String, file: StaticString = #filePath, line: UInt = #line) {
            XCTAssertThrowsError(try CTMIDIImport.convert(f, options: o), file: file, line: line) {
                XCTAssertTrue("\($0)".contains(text), "\($0)", file: file, line: line)
            }
        }
        // Nine channels with notes: the list comes back.
        refused(try CTMIDIFile(bytes: Self.fixture(extraChannels: 6)), Self.options(),
                "notes on 9 channels: 1, 2, 3, 4, 5, 6, 7, 8, 10")
        var o = Self.options()
        o.programs = [5: 1]
        refused(file, o, "programs 33 have no sample")
        o.defaultSample = 9
        XCTAssertNoThrow(try CTMIDIImport.convert(file, options: o))
        o = Self.options()
        o.drums.removeLast()
        refused(file, o, "channel 10 keys 38 have no drum pad")
        o = Self.options()
        o.transpose = 60
        refused(file, o, "outside the driver's notes 0-95")
        o = Self.options()
        o.grid = 2
        refused(file, o, "grid is 3-96")
        // A tempo the driver cannot play, and a song past $4700.
        let fast = CTMIDIFile(format: 0, division: 480, events: [.init(tick: 0, kind: .tempo(60_000)),
                                                                .init(tick: 0, kind: .noteOn(channel: 0, key: 60, velocity: 1)),
                                                                .init(tick: 480, kind: .noteOff(channel: 0, key: 60))])
        var plain = CTMIDIImport.Options()
        plain.defaultSample = 1
        refused(fast, plain, "past the driver's tempo range")
        var many: [E] = []
        for k in 0..<6000 {
            many.append(.init(tick: k * 120, kind: .noteOn(channel: 0, key: 40 + k % 40, velocity: 1)))
            many.append(.init(tick: k * 120 + 60, kind: .noteOff(channel: 0, key: 40 + k % 40)))
        }
        refused(CTMIDIFile(format: 0, division: 480, events: many), plain, "would reach $4700 (the most is 9983)")
        refused(CTMIDIFile(format: 0, division: 480, events: []), plain, "no notes")
    }

    // MARK: The driver (local ROM)

    /// The imported song, built over song 2 with the ROM's samples 1-4: the
    /// driver keys on every note at the model's step, with the note numbers
    /// the MIDI keys give and the drum pads' samples.
    func testAnImportedSongPlaysOnTheDriver() throws {
        let rom = [UInt8](try Repo.romData())
        let (text, report) = try CTMIDIImport.convert(try CTMIDIFile(bytes: Self.fixture()), options: Self.options())
        let (data, tables) = try CTSongListing.assembleSong(text)
        let (built, buildReport) = try CTROMBuilder.build(base: rom, requests: [],
                                                          songs: [.init(song: 2, source: "midi", data: data, tables: tables)], textProfile: nil)
        XCTAssertEqual(buildReport.budgets?.first?.fits, true)
        let trace = try CTSongDriverTrace.trace(rom: rom, song: 2, replacing: data, tables: tables, steps: 280)
        let comparison = try CTSongDriverTrace.compare(CTSongDocument(listing: text), tables: tables, trace: trace)
        XCTAssertTrue(comparison.passed, "\(comparison.mismatches)")
        XCTAssertEqual(Array(comparison.driverKeyOns.prefix(3)), [5, 3, 8])
        let keyOns = try CTDrumKitTrace.keyOns(clean: rom, built: built, song: 2, steps: 280)
        let melody: [Int] = keyOns.filter { $0.voice == 0 }.map { $0.number }
        XCTAssertEqual(melody, [60, 64, 67, 72, 62])
        let bass: [Int] = keyOns.filter { $0.voice == 1 }.map { $0.number }
        XCTAssertEqual(bass, [36, 43, 48])
        let drumSamples: [Int] = keyOns.filter { $0.voice == 2 }.map { $0.sample }
        XCTAssertEqual(drumSamples, [0x22, 0x23, 0x22, 0x23, 0x22, 0x23, 0x22, 0x23])
        let kit = try CTDrumKitTrace.run(clean: rom, built: built, song: 2, listing: text, steps: 280)
        XCTAssertTrue(kit.passed, "\(kit.mismatches)")
        XCTAssertEqual(report.voices.count, 3)
    }
}
